package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimShare;
import net.officefloor.hq.app.claim.ClaimShareRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.crew.CrewService;
import net.officefloor.hq.app.pool.SheetPoolMember;
import net.officefloor.hq.app.pool.SheetPoolMemberRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A steward's merge of one person into another on the same sheet. The merged person's claims move to the
 * other (numbers and dates kept, listed after the other's claims in the order they were added, each
 * keeping any figure a statement bound), and so do their statements (see {@link #carryStatements}); their name and aliases become aliases of the other; their
 * patrons are added to the other's (not the other themselves, no repeats), and anyone naming them as
 * patron names the other instead (no repeats); their pool memberships move to the other (shares added
 * where the other is already a member), and so do their crews (see {@link CrewService#personMerged}), and any due-total a closed period fixed for them is added to
 * the other's. Their holds, watchers and contact are dropped, and they leave the sheet.
 */
@Service
public class PersonMergeService {

    private final PersonRepository people;
    private final PersonPatronRepository patrons;
    private final PersonWatchRepository watches;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final SheetPoolMemberRepository poolMembers;
    private final ClaimShareRepository claimShares;
    private final CrewService crews;
    private final PeriodRepository periods;
    private final SettingsService settings;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public PersonMergeService(PersonRepository people, PersonPatronRepository patrons, PersonWatchRepository watches,
            ClaimRepository claims, StatementRepository statements, SheetPoolMemberRepository poolMembers, ClaimShareRepository claimShares,
            CrewService crews, PeriodRepository periods, SettingsService settings, SheetService sheets, RollupService rollup,
            Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.claimShares = claimShares;
        this.crews = crews;
        this.periods = periods;
        this.settings = settings;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** Merges the person {@code personId} into {@code intoId}, returning the person merged into; refused
     * unless the user is a steward, for the person themselves, and when either is retired. */
    @Transactional
    public Person merge(String sheetId, String user, long personId, long intoId) {
        Person from = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        Person into = people.findByIdAndSheetId(intoId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD || from.getId().equals(into.getId())
                || from.isRetired() || into.isRetired()) {
            throw new PersonMergeException();
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);

        List<Claim> moved = new ArrayList<>(claims.lockBySheetIdAndPersonId(sheetId, from.getId()));
        Collections.reverse(moved);
        for (Claim claim : moved) {
            claim.setPersonId(into.getId());
            claim.setListed(sheets.nextInSequence(sheetId, "listed"));
        }
        claims.flush();

        List<String> aliases = new ArrayList<>();
        aliases.add(from.getName());
        aliases.addAll(from.getAliases());

        for (PersonPatron named : patrons.findByPersonIdOrderByIdAsc(from.getId())) {
            Long patron = named.getPatronId();
            if (patron.equals(into.getId()) || patrons.existsByPersonIdAndPatronId(into.getId(), patron)) {
                patrons.delete(named);
            } else {
                named.setPersonId(into.getId());
            }
            patrons.flush();
        }
        for (PersonPatron naming : patrons.findByPatronIdOrderByIdAsc(from.getId())) {
            Long person = naming.getPersonId();
            if (person.equals(into.getId()) || patrons.existsByPersonIdAndPatronId(person, into.getId())) {
                patrons.delete(naming);
            } else {
                naming.setPatronId(into.getId());
            }
            patrons.flush();
        }

        for (SheetPoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
            var already = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
            if (already.isPresent()) {
                already.get().setShare(already.get().getShare().add(member.getShare()));
                poolMembers.delete(member);
            } else {
                member.setPersonId(into.getId());
            }
            poolMembers.flush();
        }

        // A share the merged person held passes to the person merged into, unless the claim is theirs or
        // they hold one of it already; a share they held of a claim now theirs is dropped.
        for (Claim claim : moved) {
            claimShares.findByClaimIdOrderByIdAsc(claim.getId()).stream()
                    .filter(s -> s.getPersonId().equals(into.getId())).forEach(claimShares::delete);
        }
        claimShares.flush();
        for (ClaimShare held : claimShares.findByPersonIdOrderByIdAsc(from.getId())) {
            Long claimId = held.getClaimId();
            boolean own = claims.findById(claimId).map(c -> c.getPersonId().equals(into.getId())).orElse(true);
            if (own || claimShares.findByClaimIdOrderByIdAsc(claimId).stream()
                    .anyMatch(s -> s.getPersonId().equals(into.getId()))) {
                claimShares.delete(held);
            } else {
                held.setPersonId(into.getId());
            }
            claimShares.flush();
        }

        crews.personMerged(from.getId(), into.getId());

        periods.findBySheetIdOrderByFromAsc(sheetId).forEach(period -> period.mergePersonTotal(from.getId(), into.getId()));
        periods.flush();

        carryStatements(statements, sheetId, from.getId(), sheetId, into.getId());
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
        statements.flush();
        watches.flush();

        people.delete(from);
        people.flush();
        aliases.forEach(into::addAlias);
        people.flush();

        audit.change("PERSON_MERGED", sheetId, user, "from=" + from.getName(), "into=" + into.getName());
        rollup.recordSince(sheetId, user, before);
        return into;
    }

    /**
     * Moves the statements of the person {@code fromId} on {@code fromSheetId} to the person {@code intoId}
     * on {@code intoSheetId}, keeping their order and their ids (so the claims they bound stay bound by
     * them). They are placed before the receiving person's own statements, whose last stays their last;
     * when the receiving person has none, the moved ones keep their places and their last becomes theirs.
     */
    static void carryStatements(StatementRepository statements, String fromSheetId, Long fromId,
            String intoSheetId, Long intoId) {
        List<Statement> moving = statements.inOrder(fromSheetId, fromId);
        List<Statement> own = statements.inOrder(intoSheetId, intoId);
        long first = own.isEmpty() ? 0 : own.get(0).getPosition();
        for (int i = 0; i < moving.size(); i++) {
            Statement statement = moving.get(i);
            long position = own.isEmpty() ? statement.getPosition() : first - moving.size() + i;
            statement.movedTo(intoSheetId, intoId, position);
        }
        statements.flush();
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimCommentRepository;
import net.officefloor.hq.app.claim.ClaimLineRepository;
import net.officefloor.hq.app.claim.ClaimLog;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimShareRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.crew.CrewService;
import net.officefloor.hq.app.pool.SheetPoolMemberRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A steward's transfer of a person to another sheet, by its id. The person arrives there with every grade
 * they were given (and its from-date), their terms, contact and aliases, and their claims with their
 * status, dates, notes, tags, frozen figures, logs and comments; each claim that had a number is given the
 * next number of the other sheet, in the order the claims were opened (by the sheet's today when each was
 * opened, then by the order they were added). Figures a statement bound are kept, and their statements go
 * with them (as a merge carries them, when they are merged into one already there); references are not
 * carried. The person leaves this sheet entirely: their holds, patron links, pool memberships, crew memberships and
 * watches are dropped, and the crews they lead are kept without a lead.
 */
@Service
public class PersonTransferService {

    private final PersonRepository people;
    private final PersonPatronRepository patrons;
    private final PersonWatchRepository watches;
    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final ClaimCommentRepository comments;
    private final ClaimLineRepository lines;
    private final ClaimService claimService;
    private final StatementRepository statements;
    private final SheetPoolMemberRepository poolMembers;
    private final ClaimShareRepository claimShares;
    private final CrewService crews;
    private final PeriodRepository periods;
    private final SettingsService settings;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public PersonTransferService(PersonRepository people, PersonPatronRepository patrons,
            PersonWatchRepository watches, ClaimRepository claims, ClaimLogRepository logs,
            ClaimCommentRepository comments, ClaimLineRepository lines, ClaimService claimService, StatementRepository statements,
            SheetPoolMemberRepository poolMembers, ClaimShareRepository claimShares, CrewService crews, PeriodRepository periods, SettingsService settings,
            SheetService sheets, RollupService rollup, Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.logs = logs;
        this.comments = comments;
        this.lines = lines;
        this.claimService = claimService;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.claimShares = claimShares;
        this.crews = crews;
        this.periods = periods;
        this.settings = settings;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** Transfers the person {@code personId} to the sheet {@code toSheetId} (started when it was never
     * loaded), returning them as they now are there; refused unless the user is a steward, for a retired
     * person, for this sheet's own id or an archived sheet, and when their contact is already on the other
     * sheet. When the person's name or an alias is already on the other sheet (as names are compared), they
     * are merged into the one person who has it, as a merge does: their claims are listed after that
     * person's, their name and aliases become aliases, and their contact is dropped; refused when those
     * names belong to more than one person there, or to a retired one. */
    @Transactional
    public Person transfer(String sheetId, String user, long personId, String toSheetId) {
        Person from = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD || from.isRetired() || toSheetId.equals(sheetId)) {
            throw new PersonTransferException();
        }
        Sheet to = sheets.load(toSheetId, user);
        if (to.isArchived()) throw new PersonTransferException();
        List<String> names = new ArrayList<>();
        names.add(from.getName());
        names.addAll(from.getAliases());
        Person into = null;
        for (String name : names) {
            String key = Person.keyOf(name);
            for (Person match : List.of(people.findBySheetIdAndNameKey(toSheetId, key),
                    people.findBySheetIdAndAliasKey(toSheetId, key)).stream().flatMap(Optional::stream).toList()) {
                if (into != null && !into.getId().equals(match.getId())) throw new PersonTransferException();
                into = match;
            }
        }
        if (into != null && into.isRetired()) throw new PersonTransferException();
        if (into == null && from.getContact() != null
                && people.findBySheetIdAndContact(toSheetId, from.getContact()).isPresent()) {
            throw new PersonTransferException();
        }
        RollupService.Snapshot beforeHere = rollup.snapshot(sheetId);
        RollupService.Snapshot beforeThere = rollup.snapshot(toSheetId);

        Person arrived;
        if (into != null) {
            arrived = into;
        } else {
            Person transferred = from.transferredTo(toSheetId, sheets.today(toSheetId));
            transferred.setPosition(people.maxPosition(toSheetId) + 1);
            arrived = people.saveAndFlush(transferred);
        }

        // Oldest first: each is listed anew on the other sheet in this order, so they keep their order.
        List<Claim> moving = new ArrayList<>(claims.lockBySheetIdAndPersonId(sheetId, from.getId()));
        Collections.reverse(moving);
        Map<Long, List<ClaimLog>> logsOf = moving.isEmpty() ? Map.of()
                : logs.findByClaimIdInOrderByIdAsc(moving.stream().map(Claim::getId).toList()).stream()
                        .collect(Collectors.groupingBy(ClaimLog::getClaimId));
        Map<Claim, Claim> copies = new HashMap<>();
        for (Claim claim : moving) {
            Claim copy = claim.transferredTo(toSheetId, arrived.getId());
            if (claim.isStated()) copy.bind(claim.getStatedDue(), claim.getStatedShown(), claim.getStatedBy());
            copy.setListed(sheets.nextInSequence(toSheetId, "listed"));
            copies.put(claim, copy);
        }
        Map<String, String> renumbered = new HashMap<>();
        moving.stream()
                .filter(claim -> claim.getNumber() != null)
                .sorted(Comparator.comparing((Claim claim) -> ClaimLog.openedOn(logsOf.get(claim.getId())),
                                Comparator.nullsLast(Comparator.naturalOrder()))
                        .thenComparing(Claim::getId))
                .forEach(claim -> {
                    Claim copy = copies.get(claim);
                    copy.setNumber(claimService.nextNumber(toSheetId, copy.getDueBy()));
                    renumbered.put(claim.getNumber(), copy.getNumber());
                });
        for (Claim claim : moving) {
            Claim copy = copies.get(claim);
            if (claim.getCorrects() != null) copy.setCorrects(renumbered.get(claim.getCorrects()));
            if (claim.getSplitFrom() != null) copy.setSplitFrom(renumbered.get(claim.getSplitFrom()));
        }
        for (Claim claim : moving) {
            Claim copy = claims.saveAndFlush(copies.get(claim));
            claimService.keepTags(copy);
            logs.moveClaim(claim.getId(), copy.getId());
            comments.moveClaim(claim.getId(), copy.getId());
            lines.moveClaim(claim.getId(), copy.getId());
        }
        claimShares.deleteAll(claimShares.findByClaimIdInOrderByIdAsc(moving.stream().map(Claim::getId).toList()));
        claimShares.deleteAll(claimShares.findByPersonIdOrderByIdAsc(from.getId()));
        claimShares.flush();
        claims.deleteAll(moving);
        claims.flush();

        patrons.deleteAll(patrons.findByPersonIdOrderByIdAsc(from.getId()));
